        attempt0to200Nanos = -1L
        attempt100to200Nanos = -1L
        attempt0to402Nanos = -1L
        timeAt100Nano = -1L

        startTimeNano = 0L
        startLocation = null
        accelStartNano = 0L
        distanceCompleted = false
        calibrationStartTime = 0L
        calibrationStartSpeed = 0f
        extrapolatedStartTime = 0L
